export function getCategory(entry: Entry): string { return entry.category }
export function getDisplayName(entry: Entry): string { return entry.displayName }
export function getDisplayLabel(entry: Entry): string {
  return entry.displayName.normalize('NFKC') === entry.reading.normalize('NFKC') ? entry.displayName : entry.displayName + '（' + entry.reading + '）'
}
export function getEntryReadingVariants(entry: Entry): string[] {
  const sourceReading = String(entry.source['読み方'] ?? entry.reading)
  const values = [entry.reading, sourceReading]
  return [...new Set(values.flatMap((value) => [value, ...value.split(/[／/]/)].map((item) => item.trim()).filter(Boolean)))]
}
export function getEntryExplanation(entry: Entry): string { return entry.explanation || '説明の記載はありません。' }

function normalizeSearchText(value: string): string {
  return value.normalize('NFKC').toLowerCase().replace(/[\u30a1-\u30f6]/g, (character) => String.fromCharCode(character.charCodeAt(0) - 0x60)).replace(/[\s\u3000・･、。，,.!?！？：:()（）「」『』【】\[\]]/g, '')
}
function isWithinOneEdit(query: string, candidate: string): boolean {
  if (Math.abs(query.length - candidate.length) > 1) return false
  let qi = 0, ci = 0, edits = 0
  while (qi < query.length && ci < candidate.length) {
    if (query[qi] === candidate[ci]) { qi++; ci++; continue }
    if (++edits > 1) return false
    if (query.length > candidate.length) qi++
    else if (candidate.length > query.length) ci++
    else { qi++; ci++ }
  }
  if (qi < query.length || ci < candidate.length) edits++
  return edits <= 1
}
function containsOneEditMatch(query: string, text: string): boolean {
  for (let start = 0; start < text.length; start++) for (let length = query.length - 1; length <= query.length + 1; length++) if (start + length <= text.length && isWithinOneEdit(query, text.slice(start, start + length))) return true
  return false
}
export type EntrySearchMatch = 'exact-title' | 'suggested-title' | 'related-description' | null
export function classifyEntryQuery(entry: Entry, rawQuery: string): EntrySearchMatch {
  const query = normalizeSearchText(rawQuery)
  if (!query) return null
  const aliases = [entry.name, entry.displayName, ...getEntryReadingVariants(entry)].map(normalizeSearchText)
  if (aliases.some((field) => field === query)) return 'exact-title'
  if (aliases.some((field) => field.includes(query)) || (query.length >= 3 && query.length <= 12 && aliases.some((field) => containsOneEditMatch(query, field)))) return 'suggested-title'
  if (normalizeSearchText(entry.explanation).includes(query)) return 'related-description'
  return null
}
